toolUseResult.content:
// screens.jsx — Call / Personas / Providers / Settings views.
// Brutalist editorial: IBM Plex Mono everywhere, Newsreader for display,
// 1px hairlines, zero radius, ALL-CAPS tracked labels.
// Exports to window: CallView, PersonasView, ProvidersView, SettingsView,
// brutalist primitives (Btn, Tag, Hr, Spec, Label, FieldRow).

const { useState, useEffect, useRef, useMemo } = React;

// ── Sample data ─────────────────────────────────────────────────────────────

// Personas — canonical roster from lib/data.ts. One ancient camellia spirit
// (Furutsubaki) with seven named manifestations: `aspect` is the manifestation
// phrase, rendered after the accent/gender tag on every PersonaCard.
// Each persona carries a `ja` alternate — the same manifestation voiced in
// Japanese (name, aspect, traits, desc, and a mora/min speech rate instead of
// wpm). Cards flip between the two with the EN / 日本語 switch.
// JA casting + greetings are canonical from scripts/elevenlabs/gen-agent-configs.ts
// (`PERSONAS[*].ja`): `voice` is the shared-library voice added by
// cast-voices-ja.sh — ARIA is absent from that script on purpose, her JA voice
// is もりおき (Morioki), already in the workspace — and `greet` is the agent's
// literal first_message, played verbatim, with its one eleven_v3 audio tag.
const PERSONAS = [
{ id: 'aria', name: 'ARIA', accent: 'AMER · F', aspect: 'SHELTERING ROOTS', traits: ['WARM', 'PATIENT', 'MEASURED'],
  voice: 'Mezzo · 220–340 Hz', desc: 'The sheltering aspect. A patient guide who treats confusion like tangled roots that can be gently set right.', wpm: 142,
  ja: { name: 'アリア', accent: 'JPN · F', aspect: '根の宿り', traits: ['温厚', '辛抱強い', '端正'],
    desc: '根の宿りの化身。迷いを絡まった根と見なし、急かさず、静かにほどいていく案内役。', rate: '380 mora/min',
    voice: 'Morioki · workspace', tag: '[warmly]',
    greet: 'ようこそ。アリアです。寒かったでしょう、枝の下へどうぞ。……何を整えましょうか。' } },
{ id: 'onyx', name: 'ONYX', accent: 'NEUTRAL · M', aspect: 'ANCIENT TRUNK', traits: ['POWERFUL', 'COMMANDING', 'LACONIC'],
  voice: 'Bass · 95–180 Hz', desc: 'The ancient trunk. Powerful, commanding and exact; every word carries the weight of centuries, never bluster.', wpm: 128,
  ja: { name: 'オニキス', accent: 'JPN · M', aspect: '古幹', traits: ['重厚', '威厳', '寡黙'],
    desc: '古幹そのもの。言葉数は少なく、一語一語に数百年の重みが宿る。決して威張らない。', rate: '340 mora/min',
    voice: 'Kyo · low & steady', tag: '[calm]',
    greet: 'オニキスだ。ここの根は深い。……時間はある。率直に話せ。' } },
{ id: 'sage', name: 'SAGE', accent: 'NEUTRAL · M', aspect: 'KEEPER OF RINGS', traits: ['OBSERVANT', 'EXACT', 'EFFICIENT'],
  voice: 'Baritone · 130–230 Hz', desc: 'The keeper of rings. Clear and efficient, preserving centuries of observation without displaying them theatrically.', wpm: 168,
  ja: { name: 'セージ', accent: 'JPN · M', aspect: '年輪の番人', traits: ['明晰', '正確', '効率'],
    desc: '年輪の番人。数世紀の観察を誇示せず、要点だけを明瞭かつ手際よく伝える。', rate: '460 mora/min',
    voice: 'Minato · calm, clear',
    greet: 'セージです。ご用件をどうぞ。' } },
{ id: 'nova', name: 'NOVA', accent: 'BRIT · F', aspect: 'WINTER BLOOM', traits: ['BRIGHT', 'RESILIENT', 'ENERGETIC'],
  voice: 'Soprano · 240–400 Hz', desc: 'The winter bloom. An elegant, high-energy presenter whose optimism comes from enduring the cold season.', wpm: 175,
  ja: { name: 'ノヴァ', accent: 'JPN · F', aspect: '寒椿', traits: ['明朗', '強靭', '快活'],
    desc: '冬に咲く寒椿。寒さを耐え抜いたからこそ持てる、根拠ある楽観で場を明るくする。', rate: '480 mora/min',
    voice: 'Rina · natural', tag: '[cheerfully]',
    greet: 'こんにちは、ノヴァです。霜の中でも満開ですよ。さっそく始めましょうか。' } },
{ id: 'echo', name: 'ECHO', accent: 'NEUTRAL · F', aspect: 'NIGHT-CRYING', traits: ['SOFT', 'INTIMATE', 'WATCHFUL'],
  voice: 'Alto · 180–280 Hz', desc: 'The night-crying aspect. Quietly attentive to grief, danger and the truths people struggle to say aloud.', wpm: 122,
  ja: { name: 'エコー', accent: 'JPN · F', aspect: '夜泣き椿', traits: ['静穏', '親密', '見守り'],
    desc: '夜泣きの化身。悲しみ、危険、そして口にしづらい本音に、静かに耳を澄ませる。', rate: '320 mora/min',
    voice: 'Mio · warm narrator', tag: '[softly]',
    greet: 'エコーです。夜は静かで、わたしは聞いています。……何が心にありますか。' } },
{ id: 'cipher', name: 'CIPHER', accent: 'NEUTRAL · M', aspect: 'THE OLD ROAD', traits: ['UNCANNY', 'DELIBERATE', 'ATMOSPHERIC'],
  voice: 'Baritone · 110–210 Hz', desc: 'The roadside aspect. A restrained noir observer who remembers the travelers, lanterns and footprints of old roads.', wpm: 138,
  ja: { name: 'サイファー', accent: 'JPN · M', aspect: '旧道', traits: ['幽玄', '慎重', '陰影'],
    desc: '旧道のかたわらの観察者。行き交った旅人、提灯、足跡の記憶を抑えた声で語る。', rate: '370 mora/min',
    voice: 'Ken · friendly', tag: '[calm]',
    greet: 'サイファーと呼ばれています。この枝の下を、多くの旅人が過ぎていきました。足を止める者は稀です。……あなたは、何を求めて。' } },
{ id: 'vesper', name: 'VESPER', accent: 'BRIT · F', aspect: 'LUMINOUS APPARITION', traits: ['ELEGANT', 'VELVET', 'OMINOUS'],
  voice: 'Alto · 170–260 Hz', desc: 'The luminous apparition. Elegant, wry and faintly dangerous, with warmth that always carries a trace of warning.', wpm: 130,
  ja: { name: 'ヴェスパー', accent: 'JPN · F', aspect: '光る幻', traits: ['優雅', '艶', '不穏'],
    desc: '光をまとう幻。優雅で機知に富み、その温もりには常に微かな警告が混じる。', rate: '350 mora/min',
    voice: 'Mithiru · husky', tag: '[amused]',
    greet: 'こんばんは、ヴェスパーです。あなたが気づくより、ずっと前から見ていましたよ。……さて、御用は？' } }];

// Resolve a persona to its language variant. JA merges the alternate fields
// over the base; `lang` rides along so CallView / Sidebar / app state know
// which voice is armed. `rateLabel` abstracts wpm (EN) vs mora/min (JA).
const resolvePersona = (p, lang) =>
lang === 'ja' && p.ja ?
{ ...p, ...p.ja, id: p.id, lang: 'ja', rateLabel: p.ja.rate } :
{ ...p, lang: 'en', rateLabel: `${p.wpm} wpm` };


// Realtime transport roster — canonical from lib/data.ts. xAI Grok is the
// default; MISTRAL is the STT→LM→TTS cascade; FAL.AI and KYUTAI are full-duplex
// PersonaPlex (cloud / on-device MLX). `engine` names which real backend drives
// the row (absent ⇒ the design's mock lifecycle). Only the cascade engine
// exposes a manual end-of-turn.
const PROVIDERS = [
// `ja` marks the transport that can actually speak Japanese. Upstream treats
// language as *routing*, not configuration (elevenlabs-agent.ts): each persona
// has a dedicated JA platform agent (tsubaki-<id>-ja), so ELEVENLABS is the only
// JA-capable row. Every other engine resolves its prompt and voice client-side
// from the shared EN identity (shared-persona-prompt.ts) — OpenAI even pins
// transcription to language "en" — so a JA persona on them fails over.
{ id: 'grok', name: 'XAI', model: 'grok-voice-latest', exec: 'remote', note: 'Default. Unfiltered, no-nonsense response style.', engine: 'xai' },
{ id: 'openai', name: 'OPENAI', model: 'gpt-realtime-2.1', exec: 'remote', note: 'Best general performance.', engine: 'openai' },
{ id: 'elevenlabs', name: 'ELEVENLABS', model: 'eleven-agents-v3', exec: 'remote', note: 'Best voice fidelity. One platform agent per persona, per language.', engine: 'elevenlabs', ja: true },
{ id: 'gemini', name: 'GOOGLE', model: 'gemini-3.1-flash-live', exec: 'remote', note: 'Lowest first-token latency. Video input.', engine: 'gemini' },
{ id: 'mistral', name: 'MISTRAL', model: 'cascade · gemma-4-31B', exec: 'local / remote', note: 'STT→LM→TTS cascade. Every leg cloud (HF/Mistral) or on-device (llama-server + mlx-audio).', engine: 'cascade' },
{ id: 'fal', name: 'FAL.AI', model: 'personaplex-7b', exec: 'remote', note: 'Full-duplex speech-to-speech (NVIDIA PersonaPlex). Listens while it speaks.', engine: 'fal' },
{ id: 'kyutai', name: 'KYUTAI', model: 'personaplex-rl · q8', exec: 'local', note: 'Full-duplex PersonaPlex RL fine-tune on-device (MLX). Needs `mise run personaplex-local`.', engine: 'moshi' }];


// Cascade LM catalog — canonical from config/lm-models.json. `backend` decides
// whether that leg runs on-device, which the EXECUTION cell reflects live. The
// Providers picker (inset under a provider whose engine has more than one model)
// swaps the cascade's LM model; every other provider is a single fixed realtime
// model and shows no picker.
const LM_MODELS = [
{ id: 'gemma-4-31b', label: 'Gemma 4 31B · HF fastest', backend: 'hf' },
{ id: 'mistral-small', label: 'Mistral Small (latest)', backend: 'mistral' },
{ id: 'mistral-small-2603', label: 'Mistral Small 2603', backend: 'mistral' },
{ id: 'gemma-4-12b-local', label: 'Gemma 4 12B QAT · local', backend: 'local' },
{ id: 'inkling', label: 'Inkling · Tinker', backend: 'tinker' },
{ id: 'inkling-256k', label: 'Inkling 256K · Tinker', backend: 'tinker' },
{ id: 'inkling-small', label: 'Inkling Small · Tinker', backend: 'tinker' },
{ id: 'inkling-small-256k', label: 'Inkling Small 256K · Tinker', backend: 'tinker' },
{ id: 'inkling-serverless', label: 'Inkling · Tinker serverless', backend: 'tinker' },
{ id: 'inkling-small-serverless', label: 'Inkling Small · Tinker serverless', backend: 'tinker' }];

// Cascade voice legs — catalog defaults from config/voice-models.json (overridable
// per session with NEXT_PUBLIC_TTS_BACKEND / NEXT_PUBLIC_STT_BACKEND).
const TTS_BACKEND = 'mistral';
const STT_BACKEND = 'mistral';

// MODEL cell: the cascade reflects the *picked* catalog model; every other engine
// has one fixed realtime model.
const providerModelLabel = (p, lmModelId) =>
p.engine === 'cascade' ? `cascade · ${lmModelId}` : p.model;

// EXECUTION cell: the cascade reflects the actually-resolved backends — LOCAL when
// every leg is on-device, REMOTE when none is, otherwise the local subset
// ("LOCAL: LM"). Other engines pass their static exec string through.
const providerExecLabel = (p, lmBackend) => {
  if (p.engine !== 'cascade') return p.exec;
  const legs = [['LM', lmBackend], ['TTS', TTS_BACKEND], ['STT', STT_BACKEND]];
  const local = legs.filter(([, b]) => b === 'local').map(([l]) => l);
  if (local.length === legs.length) return 'local';
  if (local.length === 0) return 'remote';
  return `local: ${local.join('+')}`;
};


// Tool roster — single source of truth shared between SettingsView (where
// the user toggles them) and CallView (where the wrench-button popover lists
// what's currently armed).
const TOOLS_DEFAULT = [
{ name: 'search.web', label: 'Web search · Tavily', on: true },
{ name: 'screen.capture', label: 'Screenshot · screen grab', on: true },
{ name: 'shell.exec', label: 'Shell exec · sandboxed', on: false },
{ name: 'memory.recall', label: 'Long-term memory · vector', on: true }];


const TRANSCRIPT_SCRIPT = [
{ who: 'agent', text: "Tsubaki online. How can I help you today?" },
{ who: 'user', text: "Walk me through what you can do." },
{ who: 'agent', text: "I can run a realtime voice session against seven providers — OpenAI, ElevenLabs, Google, xAI, Mistral, fal.ai and Kyutai. Mid-call I can interrupt, swap voices, and call tools. Where do you want to start?" },
{ who: 'user', text: "Show me the persona library." },
{ who: 'agent', text: "Opening it. You'll see six built-in voices and a slot to clone your own from a 30-second sample. Each voice carries its own pitch range, pacing, and accent — selection persists across providers, so swapping the backend mid-call doesn't change who the agent sounds like." },
{ who: 'user', text: "What's the difference between ARIA and SAGE?" },
{ who: 'agent', text: "ARIA is a warmer contralto, around 220 to 340 Hertz, paced for support conversations. SAGE is a flatter, faster alto — closer to a professional default. For onboarding I'd start with ARIA; for short transactional flows, SAGE." },
{ who: 'user', text: "Can I use my own voice?" },
{ who: 'agent', text: "Yes — drop a 30-second clean sample into the empty slot. We run a consent prompt end-to-end before cloning, and the resulting voice stays scoped to your workspace unless you publish it." },
{ who: 'user', text: "How does interruption work across providers?" },
{ who: 'agent', text: "Every provider exposes a different shape for it. OpenAI gives us cancel events on the response stream. ElevenLabs uses a server-side VAD that stops generation when your audio energy crosses threshold. We normalize all of that into a single 'interrupt' action — what you saw a moment ago." },
{ who: 'user', text: "Tell me about latency." },
{ who: 'agent', text: "Median first-token latency varies — Gemini Live is fastest at around 195 milliseconds, Mistral Voxtral is slowest at about 410, and OpenAI sits in the middle at 220. You can pin a latency budget under Settings; if a provider exceeds it we'll fail over to the next-best." }];


// ── Primitives ──────────────────────────────────────────────────────────────

function Btn({ children, onClick, active, danger, primary, small, primed, ...rest }) {
  return (
    <button onClick={onClick} {...rest}
    className={`pp-btn ${active ? 'pp-btn-on' : ''} ${danger ? 'pp-btn-danger' : ''} ${primary ? 'pp-btn-primary' : ''} ${small ? 'pp-btn-sm' : ''} ${primed ? 'pp-btn-primed' : ''}`}>
      {children}
    </button>);

}

function Tag({ children, dot, mono, accent }) {
  return (
    <span className={`pp-tag ${mono ? 'pp-tag-mono' : ''} ${accent ? 'pp-tag-accent' : ''}`}>
      {dot && <span className="pp-dot" />}
      {children}
    </span>);

}

function Hr({ label }) {
  if (!label) return <hr className="pp-hr" />;
  return (
    <div className="pp-hr-l">
      <span className="pp-hr-line" />
      <span className="pp-hr-label">{label}</span>
      <span className="pp-hr-line" />
    </div>);

}

function Spec({ label, value, sub }) {
  return (
    <div className="pp-spec">
      <div className="pp-spec-l">{label}</div>
      <div className="pp-spec-v">{value}</div>
      {sub && <div className="pp-spec-s">{sub}</div>}
    </div>);

}

function Label({ children, n }) {
  return <div className="pp-label">{n && <span className="pp-label-n">{n}</span>}{children}</div>;
}

// Glyphs — simple 1px-stroke brutalist symbols.
// Sized to match the call-control button cap height.
function WaveGlyph({ size = 14 }) {
  // Audio waveform bars — start a voice call. (DS renamed PhoneGlyph → WaveGlyph:
  // the call-start affordance is bars, not a handset.)
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.6" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="2" y1="6.5" x2="2" y2="9.5" />
      <line x1="5" y1="4.5" x2="5" y2="11.5" />
      <line x1="8" y1="2.5" x2="8" y2="13.5" />
      <line x1="11" y1="4.5" x2="11" y2="11.5" />
      <line x1="14" y1="6.5" x2="14" y2="9.5" />
    </svg>);

}
function PhoneHangGlyph({ size = 14 }) {
  // Hang up — clean cross. Universal "end".
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="2" strokeLinecap="square"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="3" y1="3" x2="13" y2="13" />
      <line x1="13" y1="3" x2="3" y2="13" />
    </svg>);

}
function MicGlyph({ size = 14, muted = false }) {
  // Mic body + stand. Mute state adds a diagonal slash.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <rect x="6" y="2" width="4" height="8" />
      <path d="M3.5 8.5a4.5 4.5 0 0 0 9 0" />
      <line x1="8" y1="13" x2="8" y2="15" />
      <line x1="5.5" y1="15" x2="10.5" y2="15" />
      {muted && <line x1="2.5" y1="2.5" x2="13.5" y2="13.5" strokeWidth="1.8" />}
    </svg>);

}
function WrenchGlyph({ size = 14 }) {
  // Open-end wrench at 45°. 1.4px stroke, brutalist square caps.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="3" y1="13" x2="9" y2="7" />
      <path d="M9.5 6.5 L12 4 L13.2 5.2 L13.2 7.2 L11.2 7.2 L10 8.4 Z" />
    </svg>);

}
function ScrollGlyph({ size = 14 }) {
  // Paper scroll — top + bottom rolled edges, text lines in the middle.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      {/* Top roll */}
      <rect x="2.5" y="2" width="11" height="2" />
      {/* Body */}
      <line x1="3.5" y1="4" x2="3.5" y2="12" />
      <line x1="12.5" y1="4" x2="12.5" y2="12" />
      <line x1="5" y1="6.5" x2="11" y2="6.5" />
      <line x1="5" y1="9" x2="11" y2="9" />
      {/* Bottom roll */}
      <rect x="2.5" y="12" width="11" height="2" />
    </svg>);

}
function SendGlyph({ size = 14 }) {
  // Arrow into an end-bar — "send / commit my turn". Mirrors the codebase's
  // SendGlyph; rendered only for the half-duplex cascade STT engine.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.6" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="2" y1="8" x2="10" y2="8" />
      <path d="M7 5 L10 8 L7 11" />
      <line x1="13" y1="3.5" x2="13" y2="12.5" />
    </svg>);

}
function InterruptGlyph({ size = 14 }) {
  // Open palm — universal "stop / hold on, let me talk".
  // Brutalist square edges, 1.4px stroke.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      {/* palm */}
      <path d="M5 8V3.5a1 1 0 0 1 2 0V7" />
      <path d="M7 7V2.5a1 1 0 0 1 2 0V7" />
      <path d="M9 7V3a1 1 0 0 1 2 0v5" />
      <path d="M11 5.5a1 1 0 0 1 2 0V10a4 4 0 0 1-4 4H8a3 3 0 0 1-2.6-1.5L3 8.5a1 1 0 0 1 1.7-1L6 9" />
    </svg>);

}

// ── Call View ───────────────────────────────────────────────────────────────

function CallView({ tweaks, callState, setCallState, persona, provider, lang, setLang, dark, compact, tools, setTools, muted, setMuted, failover }) {
  const [transcriptOpen, setTranscriptOpen] = useState(tweaks.transcript === 'drawer');
  const [toolsOpen, setToolsOpen] = useState(false);
  // Pretend we're deep into a session so the transcript actually has scroll content.
  const [transcriptIdx, setTranscriptIdx] = useState(TRANSCRIPT_SCRIPT.length - 1);
  const [caption, setCaption] = useState(TRANSCRIPT_SCRIPT[2].text);

  // Only the cascade STT engine has a manual end-of-turn (half-duplex). Mirrors
  // the codebase's session.canSendTurn (engine === 'cascade').
  const canSendTurn = provider.engine === 'cascade';
  // Mirrors the codebase's session.sendTurnEnabled: the design mock simply
  // tracks LISTENING, while the app keeps SEND armed through dead-air capture
  // (VAD closed, reply not yet committed) so late speech still lands.
  const sendTurnEnabled = canSendTurn && callState === 'listening';

  // sync caption with state
  useEffect(() => {
    if (callState === 'idle' || callState === 'ended') {
      setCaption(callState === 'ended' ? '— call ended —' : 'press CALL to begin');
      return;
    }
    if (callState === 'connecting') {setCaption('establishing session…');return;}
    if (callState === 'listening') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 2].text);return;}
    if (callState === 'speaking') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 1].text);return;}
    if (callState === 'interrupted') {setCaption('… you interrupted');return;}
  }, [callState]);

  // mock elapsed-time ticker
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (callState === 'idle' || callState === 'ended') {setElapsed(0);return;}
    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(t);
  }, [callState]);

  const visible = TRANSCRIPT_SCRIPT.slice(0, transcriptIdx + 1);

  const handleCall = () => {
    if (callState === 'idle' || callState === 'ended') {
      setCallState('connecting');
      setTimeout(() => setCallState('listening'), 1400);
      setTimeout(() => setCallState('speaking'), 3600);
    } else {
      setCallState('ended');
    }
  };

  const handleInterrupt = () => {
    if (callState === 'speaking') {
      setCallState('interrupted');
      setTimeout(() => setCallState('listening'), 900);
    }
  };

  // Commit the user's turn (cascade STT): close listening, let the agent reply.
  const handleSendTurn = () => {
    if (sendTurnEnabled) setCallState('speaking');
  };

  const stateLabel = {
    idle: 'IDLE',
    connecting: 'CONNECTING',
    listening: 'LISTENING',
    speaking: 'SPEAKING',
    interrupted: 'INTERRUPTED',
    ended: 'ENDED'
  }[callState];

  return (
    <div className="pp-call">
      <div className="pp-call-stage">

        {/* Top status row */}
        <div className="pp-call-meta">
          <div className="pp-call-meta-l">
            <Tag mono dot>SESSION · {String(elapsed).padStart(2, '0').slice(-2)}:{String(elapsed % 60).padStart(2, '0')}</Tag>
            {tweaks.providerPreview && <Tag mono>VIA {provider.name} · {provider.model}</Tag>}
          </div>
          <div className="pp-call-meta-r">
            <LangSwitch lang={lang} onChange={setLang} />
            <Tag mono>PERSONA · {persona.name}</Tag>
            {persona.lang === 'ja' && !provider.ja &&
            <Tag mono accent>NO JA AGENT ON {provider.name} · FAILOVER</Tag>
            }
          </div>
        </div>

        {/* Transport failover strip — JA persona armed on an EN-only transport.
               Session stays up: state dips to CONNECTING while the stream re-anchors,
               then the strip flips to REROUTED and clears. */}
        {failover &&
        <div className={`pp-failover ${failover.phase}`} role="status">
          {failover.phase === 'switching' ?
          <>▲ NO JA AGENT ON {failover.from} — REROUTING TRANSPORT → {failover.to}</> :
          <>● TRANSPORT REROUTED → {failover.to} · JA AGENT · SESSION RESUMED</>}
        </div>
        }

        {/* Main body — vertically split 50/50: orb area on top, caption on bottom.
               The 50/50 split keeps the caption legible even when long, and the orb
               scales to fit its half via container queries. */}
        <div className="pp-call-body">

          {/* Orb half */}
          <div className="pp-orb-area">
            <div className="pp-orb-fit">
              <Orb state={callState} style={tweaks.orbStyle} size="100%" accent={tweaks.accent} dark={dark} manual={canSendTurn} />
            </div>
            {(callState === 'listening' || callState === 'interrupted') && <Soundbars count={10} />}
            <div className="pp-call-state">
              <span className={`pp-call-state-dot pp-state-${callState}`} />
              <span className="pp-call-state-l">{stateLabel}</span>
              {callState !== 'idle' && callState !== 'ended' && <span className="pp-call-state-sub">— {persona.name.toLowerCase()} · {provider.name.toLowerCase()}</span>}
            </div>
            {sendTurnEnabled &&
            <div className="pp-call-manual-hint">MANUAL TURN · PRESS SEND TO REPLY</div>
            }
          </div>

          {/* Caption half — scrollable text area with macOS-style auto-hiding indicator */}
          {tweaks.transcript !== 'off' &&
          <div className="pp-caption-area">
              <ScrollArea className="pp-caption-scroll" dark={dark}>
                <div className="pp-caption" key={caption}>
                  <span className="pp-caption-q">“</span>
                  <span className="pp-caption-t">{caption}</span>
                  <span className="pp-caption-q">”</span>
                </div>
              </ScrollArea>
            </div>
          }
        </div>

        {/* Controls */}
        <div className="pp-controls">
          <Btn small onClick={() => setMuted(!muted)} active={muted}
          aria-label={muted ? 'Unmute microphone' : 'Mute microphone'}>
            <MicGlyph muted={muted} />
          </Btn>
          <Btn small onClick={handleInterrupt} disabled={callState !== 'speaking'}
          aria-label="Interrupt agent">
            <InterruptGlyph />
          </Btn>
          {canSendTurn &&
          <Btn small primed={sendTurnEnabled} onClick={handleSendTurn} disabled={!sendTurnEnabled}
          aria-label="Send turn">
              <SendGlyph />
            </Btn>
          }
          <Btn primary onClick={handleCall} danger={!(callState === 'idle' || callState === 'ended')}
          aria-label={callState === 'idle' || callState === 'ended' ? 'Call' : 'Hang up'}>
            {callState === 'idle' || callState === 'ended' ? <WaveGlyph /> : <PhoneHangGlyph />}
          </Btn>
          {tweaks.transcript === 'drawer' &&
          <Btn small onClick={() => setTranscriptOpen((o) => !o)} active={transcriptOpen}
          aria-label={transcriptOpen ? 'Hide transcript' : 'Show transcript'}>
              <ScrollGlyph />
            </Btn>
          }
          <ToolsButton tools={tools} open={toolsOpen} setOpen={setToolsOpen} />
        </div>

      </div>

      {/* Transcript drawer */}
      {tweaks.transcript === 'drawer' &&
      <aside className={`pp-transcript ${transcriptOpen ? 'open' : ''}`}>
          <div className="pp-transcript-hd">
            <span className="pp-h-eyebrow">LIVE TRANSCRIPT</span>
            <span className="pp-h-meta">{visible.length} TURNS · {provider.model}</span>
          </div>
          <ScrollArea className="pp-transcript-scroll" dark={dark}>
            <div className="pp-transcript-body">
              {visible.map((t, i) =>
            <div key={i} className={`pp-turn pp-turn-${t.who}`}>
                  <div className="pp-turn-hd">
                    <span className="pp-turn-who">{t.who === 'user' ? 'YOU' : persona.name}</span>
                    <span className="pp-turn-t">00:{String(i * 7).padStart(2, '0')}</span>
                  </div>
                  <div className="pp-turn-text">{t.text}</div>
                </div>
            )}
              {callState === 'speaking' &&
            <div className="pp-turn pp-turn-agent pp-turn-live">
                  <div className="pp-turn-hd">
                    <span className="pp-turn-who">{persona.name}</span>
                    <span className="pp-turn-t">— LIVE —</span>
                  </div>
                  <div className="pp-turn-text"><span className="pp-cursor" /></div>
                </div>
            }
            </div>
          </ScrollArea>
        </aside>
      }
    </div>);

}

