  const r = resolvePersona(p, lang);
  const ja = lang === 'ja';
  return (
    <div className={`pp-persona-card ${on ? 'on' : ''}`} onClick={() => onSelect(r)}>
      <div className="pp-persona-top">
        <div className="pp-persona-num">{String(index + 1).padStart(2, '0')}</div>
        <div className="pp-persona-top-r">
          <div
            className="pp-persona-dot"
            style={{
              background: on ? accent : `color-mix(in srgb, ${accent} 26%, #000)`,
              boxShadow: on ? `0 0 0 4px color-mix(in srgb, ${accent} 22%, transparent)` : 'none'
            }}
            role="img"
            aria-label={t(on ? 'aria.activePersona' : 'aria.inactivePersona')} />
        </div>
      </div>
      <div className="pp-persona-name">
        {r.name}
        {ja && <span className="pp-name-sub" lang="en">{p.name}</span>}
      </div>
      <div className="pp-persona-accent">{r.accent} · {r.aspect}</div>
      <div className="pp-persona-traits">
        {(full ? r.traits : r.traits.slice(0, 2)).map((trait) => <span key={trait} className="pp-trait">{trait}</span>)}
      </div>
      {full && <p className="pp-persona-desc">{r.desc}</p>}
      {full && ja && r.greet &&
      <div className="pp-ja-greet">
        <span className="pp-ja-greet-l">{t('personas.firstMessage')}{r.tag && <span className="pp-ja-greet-tag" lang="en">{r.tag}</span>}</span>
        <span className="pp-ja-greet-t">{r.greet}</span>
      </div>
      }
      {full && ja &&
      <div className="pp-ja-support">
        <span className="pp-ja-support-l">{t('personas.jaAgent')}</span>
        <span className="pp-ja-support-v">{JA_PROVIDER().name} · {jaAgentName(p)}</span>
      </div>
      }
      {full &&
      <div className="pp-persona-foot">
        <span className="pp-mono-num">{r.rateLabel}</span>
        <span className="pp-mono-num">{r.voice}</span>
      </div>
      }
    </div>);
}

function PersonasView({ persona, setPersona, lang, setLang, accent }) {
  const t = useT();
  return (
    <div className="pp-personas">
      <div className="pp-page-hd">
        <div>
          <div className="pp-h-eyebrow">{t('personas.eyebrow')}</div>
          <h1 className="pp-h1">{t('personas.title')}</h1>
          <p className="pp-lede">{t('personas.lede')}</p>
        </div>
        <div className="pp-page-hd-r">
