            <LangSwitch lang={lang} onChange={setLang} />
          </span>
          <Btn small>{t('personas.clone')}</Btn>
          <Btn small>{t('personas.import')}</Btn>
        </div>
      </div>

      <div className="pp-grid">
        {PERSONAS.map((p, i) =>
        <PersonaCard key={p.id} p={p} index={i} lang={lang} on={persona.id === p.id}
        accent={accent} full onSelect={setPersona} />
        )}

