        <FieldRow label={t('field.language')}>
          <LangSwitch lang={lang} onChange={setLang} />
        </FieldRow>
      </div>
      <div className="pp-settings-sec">
        <Hr label={t('sec.audioIn')} />
        <FieldRow label={t('field.input')}>
          <MicSelector value={mic} onChange={setMic} muted={muted} onMutedChange={setMuted} />
        </FieldRow>
        <FieldRow label={t('field.denoise')}>
          <SwitchRow value={true} onChange={() => {}} />
        </FieldRow>
        <FieldRow label={t('field.ptt')} hint={t('field.ptt.hintShort')}>
          <SwitchRow value={false} onChange={() => {}} />
        </FieldRow>
      </div>
      <div className="pp-settings-sec">
        <Hr label={t('sec.behaviour')} />
        <FieldRow label={t('field.latencyShort', { ms: 220 })}>
          <input type="range" min="80" max="600" defaultValue="220" className="pp-range" style={{ accentColor: accent }} />
        </FieldRow>
        <FieldRow label={t('field.interruptions')} hint={t('field.interruptions.hintShort')}>
          <SwitchRow value={true} onChange={() => {}} />
        </FieldRow>
      </div>
      <div className="pp-settings-sec">
        <Hr label={t('sec.tools')} />
        {tools.map((tool) =>
        <ToolRow key={tool.name} name={tool.name} label={tool.label} on={tool.on}
        onToggle={() => setTools((prev) => prev.map((x) => x.name === tool.name ? { ...x, on: !x.on } : x))} />
        )}
      </div>
    </div>);
}

function MobileTabs({ nav, setNav }) {
  const t = useT();
  return (
    <nav className="pp-mobile-tabs">
      {NAV.map((item) =>
      <button key={item.id}
      className={`pp-mobile-tab ${nav === item.id ? 'on' : ''}`}
      onClick={() => setNav(item.id)}>
          {t(`nav.${item.id}`)}
        </button>
      )}
    </nav>);
}

Object.assign(window, { DesktopApp, MobileApp });

