def rep(a,b):
    global s
    assert s.count(a)==1, a[:70]; s=s.replace(a,b)

rep("""// app.jsx — Desktop + Mobile app shells. Each owns its own call state and its
// own session routing (transport + language, via useSessionRouting).""",
"""// app.jsx — Desktop + Mobile app shells. Each owns its own call state and its
// own session routing (transport + language, via useSessionRouting). Both shells
// render the same four sections from the same views; mobile reaches them from a
// slide-in sidebar drawer (the desktop Sidebar, reused) instead of a fixed rail.""")

rep("""function TopBar({ compact, callState }) {""", """function TopBar({ compact, callState, onMenu, menuOpen }) {""")
rep("""      <div className="pp-brand">
