const m = document.querySelector('#mob'), d = document.querySelector('#desk');
const menu = m.querySelector('.pp-menu-btn');
const before = { tabs: !!m.querySelector('.pp-mobile-tabs'), layerVis: getComputedStyle(m.querySelector('.pp-drawer-layer')).visibility, aria: menu?.getAttribute('aria-label') };
menu.click(); await new Promise(r=>setTimeout(r,300));
const opened = { vis: getComputedStyle(m.querySelector('.pp-drawer-layer')).visibility, expanded: menu.getAttribute('aria-expanded'), items: [...m.querySelectorAll('.pp-drawer .pp-nav-item')].map(x=>x.innerText.split('\n')[0]) };
[...m.querySelectorAll('.pp-drawer .pp-nav-item')][3].click(); await new Promise(r=>setTimeout(r,300));
const settings = { closed: getComputedStyle(m.querySelector('.pp-drawer-layer')).visibility, secs: [...m.querySelectorAll('.pp-settings-sec .pp-hr-label')].map(x=>x.innerText), fields: m.querySelectorAll('.pp-field').length, mic: m.querySelector('.pp-micsel-label')?.innerText };
// desktop settings order
d.querySelectorAll('.pp-nav-item')[3].click(); await new Promise(r=>setTimeout(r,200));
const secs = [...d.querySelectorAll('.pp-settings-sec')].map(s => ({ label: s.querySelector('.pp-hr-label').innerText, x: Math.round(s.getBoundingClientRect().left - d.getBoundingClientRect().left), w: Math.round(s.getBoundingClientRect().width) }));
// mobile providers + personas
