63	.pp-mobile .pp-page-hd-r { flex-wrap: wrap; }
64	.pp-mobile .pp-grid { grid-template-columns: 1fr; }
65	/* Provider notes don't fit at 390px; the active provider's specs below the
66	   table carry the detail instead. */
67	.pp-mobile .pp-th-note, .pp-mobile .pp-table-note { display: none; }
68	.pp-mobile .pp-prov-detail { padding: 8px 14px 18px; }
69	.pp-mobile .pp-prov-specs { grid-template-columns: 1fr 1fr; gap: 8px; }
70	.pp-mobile .pp-settings-sec { border-right: 0; }
71	
72	/* Reserve the transcript sheet's collapsed handle strip (32px, bottom-docked)
73	   under the call controls now that no tab bar sits between them. */
74	.pp-mobile-controls.pp-mobile-controls-sheet { padding-bottom: calc(14px + 32px); }

